@import "colors";
@error: @red;

@font-size: 14px;
@padding-y-large: 12px;
@padding-x-large: 10px;
@padding-y-medium: 8px;
@padding-x-medium: 10px;
@padding-y-small: 6px;
@padding-x-small: 10px;


.form-field {
  color: #0D0C0B;
  font-size: @font-size;
  height: inherit;
  width: 100%;
  border-radius: 4px;
  border: 1px solid @gray60 !important;
  &.large {
    padding: @padding-y-large @padding-x-large;
    & + label {
      top: @padding-y-large;
    }
  }
  &.medium {
    padding: @padding-y-medium @padding-x-medium;
    & + label {
      top: @padding-y-medium;
    }
  }
  &.small {
    padding: @padding-y-small @padding-x-small;
    & + label {
      top: @padding-y-small;
    }
  }
  &.error, &.has-right-icon {
    padding-right: 45px;
  }
  &.error {
    border: 1px solid @error !important;
    & ~ label {
      color: @error !important;
    }
    &:focus, &:hover {
      border: 1px solid @error !important;
      caret-color: @error;
    }
  }
  &.has-left-icon {
    padding-left: 45px;
    & + label {
      left: 45px;
    }
  }
  &:hover {
    border: 1px solid #000 !important;
  }
  &:focus, &.item-focus {
    border: 1px solid @primary-color !important;
    caret-color: @primary-color;
    & + label {
      color: @primary-color;
      font-size: 11px;
      top: -8px;
      left: 8px;
      padding: 0 4px;
      background-color: #fff;
    }
  }
}

.text-field-container {
  input {
    &::placeholder {
      visibility: hidden;
      opacity: 0;
      transition: visibility 0.1s ease-out, opacity 0.1s ease-out;
      padding: 0 4px;
    }
    &:focus {
      &::placeholder {
        visibility: visible;
        opacity: 1;
      }
    }
  }
}

.sp-input-container {
  margin: 0;
  position: relative;
  input {
    box-shadow: none;
    outline: none;
    // max-width: 520px;
    min-height: 24px;
    .form-field();

    &[disabled] {
      background-color: #ffffff !important;
      color: @gray40 !important;
      border: 1px solid @gray40 !important;
      cursor: not-allowed;
      & ~ label {
        color: @gray40 !important;
      }
      &:hover {
        border: 1px solid @gray40 !important;
      }
